import assert from 'node:assert/strict';
const base=new URL(process.argv[2]);if(!(/^https:\/\/[a-z0-9-]+\.trycloudflare\.com$/.test(base.origin)||/^http:\/\/127\.0\.0\.1:\d+$/.test(base.origin)))throw new Error('Private preview origin required');
const health=await fetch(new URL('/api/health',base));assert.equal(health.status,200);if(process.env.GITHUB_SHA)assert.equal(health.headers.get('x-sds-private-source'),process.env.GITHUB_SHA);
const start=await fetch(new URL('/start.md',base));assert.equal(start.status,200);const text=await start.text();assert.match(text,/free route check/i);assert.match(text,/check_ai_readiness/);
const target='https://example.com',path='/api/tools/ai-readiness?url='+encodeURIComponent(target);
const response=await fetch(new URL(path,base));const http=await response.json();assert.equal(response.status,200,JSON.stringify(http));assert.ok(Array.isArray(http.checks));
const {spawnSync}=await import('node:child_process');const cli=spawnSync('curl',['--fail','--silent','--show-error',new URL(path,base).href],{encoding:'utf8',timeout:30000});assert.equal(cli.status,0);const command=JSON.parse(cli.stdout);assert.equal(command.url,http.url);assert.equal(command.score,http.score);
const post=async(method,params,id=1)=>{const r=await fetch(new URL('/mcp',base),{method:'POST',headers:{'Content-Type':'application/json',Accept:'application/json, text/event-stream','MCP-Protocol-Version':'2025-11-25'},body:JSON.stringify({jsonrpc:'2.0',id,method,params})});assert.equal(r.status,200);const body=await r.text();return JSON.parse(body.startsWith('data:')?body.slice(5):body);};
const init=await post('initialize',{protocolVersion:'2025-11-25',capabilities:{},clientInfo:{name:'sds-private-cold-acceptance',version:'1'}});assert.equal(init.result.protocolVersion,'2025-11-25');const tools=await post('tools/list',{});assert.ok(tools.result.tools.some(t=>t.name==='check_ai_readiness'));const call=await post('tools/call',{name:'check_ai_readiness',arguments:{url:target}});assert.equal(call.result.isError,undefined);const output=call.result.structuredContent||JSON.parse(call.result.content.find(c=>c.type==='text').text);assert.equal(output.url,http.url);assert.equal(output.score,http.score);console.log(JSON.stringify({received:true,paths:['start.md','CLI curl','HTTP route check','MCP initialize/list/call'],free:true,paid:false,paymentSent:false,score:http.score}));
